  awardRFQ: (rfqId: string, vendorId: string) =>
    request<RFQ>(`/api/rfqs/${rfqId}/award/${vendorId}`, { method: "POST" }),

  submitRFQResponse: (rfqId: string, data: { vendor_id: string; unit_price?: number; delivery_days?: number; validity_days?: number; notes?: string }) =>
    request<RFQResponse>(`/api/rfqs/${rfqId}/responses`, {
