                      <TableCell className="font-mono text-sm">{item.employee_id}</TableCell>
                      <TableCell>{item.work_type}</TableCell>
                      <TableCell>{item.reference_id}</TableCell>
                      <TableCell>{item.project_name}</TableCell>
                      <TableCell>{item.hours_logged}</TableCell>
                      <TableCell>{item.billable_hours}</TableCell>
                      <TableCell>
                        <Button variant="ghost" asChild>
                          <Link to={`/time-logs/${item.id}`}>View</Link>
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          <div className="flex items-center justify-between mt-4">
            <span className="text-sm text-muted-foreground">
              {total} time log{total !== 1 ? "s" : ""}
            </span>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
              >
                <ArrowLeft className="h-4 w-4" />
              </Button>
              <span className="text-sm">Page {page} of {totalPages}</span>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page >= totalPages}
              >
                <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

